from math import ceil, erfc, sqrt

def two_prop_z(x1, n1, x2, n2):
    p1, p2 = x1 / n1, x2 / n2
    p = (x1 + x2) / (n1 + n2)
    se = sqrt(p * (1 - p) * (1 / n1 + 1 / n2))
    z = (p2 - p1) / se
    pval = erfc(abs(z) / sqrt(2))
    se_d = sqrt(p1 * (1 - p1) / n1 + p2 * (1 - p2) / n2)
    ci = (p2 - p1 - 1.96 * se_d, p2 - p1 + 1.96 * se_d)
    return z, pval, ci

def sample_size(p, delta, za=1.96, zb=0.84):
    var = p * (1 - p) + (p + delta) * (1 - p - delta)
    return ceil((za + zb) ** 2 * var / delta ** 2)

