import numpy as np

def stump(X, y, w):
    best = (np.inf, 0, 0.0, 1)
    for j in range(X.shape[1]):
        for t in np.unique(X[:, j])[:-1]:
            for s in (1, -1):
                p = np.where(X[:, j] <= t, s, -s)
                e = w[p != y].sum()
                if e < best[0]:
                    best = (e, j, t, s)
    return best

def adaboost(X, y, T=20):
    w = np.full(len(y), 1 / len(y))
    model = []
    for _ in range(T):
        e, j, t, s = stump(X, y, w)
        a = 0.5 * np.log((1 - e) / max(e, 1e-12))
        p = np.where(X[:, j] <= t, s, -s)
        w = w * np.exp(-a * y * p)
        w /= w.sum()
        model.append((a, j, t, s))
    return model

def predict(model, X):
    f = np.zeros(len(X))
    for a, j, t, s in model:
        f += a * np.where(X[:, j] <= t, s, -s)
    return np.sign(f)

import numpy as np

def init_state(w):
    return {"m": np.zeros_like(w), "v": np.zeros_like(w), "t": 0}

def adam_step(w, g, st, lr=1e-3, b1=0.9, b2=0.999, eps=1e-8):
    st["t"] += 1
    st["m"] = b1 * st["m"] + (1 - b1) * g
    st["v"] = b2 * st["v"] + (1 - b2) * g * g
    m_hat = st["m"] / (1 - b1 ** st["t"])
    v_hat = st["v"] / (1 - b2 ** st["t"])
    return w - lr * m_hat / (np.sqrt(v_hat) + eps)

