import numpy as np

def beam_search(step, bos, L, B):
    beams = [([bos], 0.0)]
    for _ in range(L):
        cand = []
        for seq, sc in beams:
            lp = step(seq)
            for t in range(len(lp)):
                cand.append((seq + [t], sc + lp[t]))
        cand.sort(key=lambda c: -c[1])
        beams = cand[:B]
    return beams

