from collections import Counter

def ngrams(t, n):
    return Counter(tuple(t[i:i + n]) for i in range(len(t) - n + 1))

def corpus_bleu(hyps, refs, max_n=4):
    match, total = np.zeros(max_n), np.zeros(max_n)
    hl = rl = 0
    for h, r in zip(hyps, refs):
        hl, rl = hl + len(h), rl + len(r)
        for n in range(1, max_n + 1):
            hn, rn = ngrams(h, n), ngrams(r, n)
            match[n - 1] += sum(min(c, rn[g]) for g, c in hn.items())
            total[n - 1] += max(len(h) - n + 1, 0)
    if match.min() == 0:
        return 0.0
    bp = 1.0 if hl > rl else np.exp(1 - rl / hl)
    return 100 * bp * np.exp(np.log(match / total).mean())

from collections import Counter

def merge(s, a, b):
    out, i = [], 0
    while i < len(s):
        if i < len(s) - 1 and (s[i], s[i + 1]) == (a, b):
            out.append(a + b)
            i += 2
        else:
            out.append(s[i])
            i += 1
    return out

def bpe_train(words, k):
    seqs, merges = [list(w) for w in words], []
    for _ in range(k):
        cnt = Counter()
        for s in seqs:
            cnt.update(zip(s, s[1:]))
        if not cnt:
            break
        a, b = min(cnt, key=lambda p: (-cnt[p], p))
        seqs = [merge(s, a, b) for s in seqs]
        merges.append((a, b))
    return merges

def bpe_encode(word, merges):
    s = list(word)
    for a, b in merges:
        s = merge(s, a, b)
    return s

