import numpy as np

def dbscan(X, eps, min_pts):
    n = len(X)
    D = np.linalg.norm(X[:, None] - X[None], axis=2)
    nbrs = [np.flatnonzero(D[i] <= eps) for i in range(n)]
    core = np.array([len(nb) >= min_pts for nb in nbrs])
    labels = np.full(n, -1)
    c = 0
    for i in range(n):
        if labels[i] != -1 or not core[i]:
            continue
        labels[i] = c
        stack = [i]
        while stack:
            j = stack.pop()
            if not core[j]:
                continue
            for k in nbrs[j]:
                if labels[k] == -1:
                    labels[k] = c
                    stack.append(k)
        c += 1
    return labels

import numpy as np

def gini(y):
    p = np.bincount(y) / len(y)
    return 1 - p @ p

def grow(X, y, depth):
    best, leaf = (gini(y), None, None), np.bincount(y).argmax()
    if depth == 0 or best[0] == 0:
        return leaf
    for j in range(X.shape[1]):
        v = np.unique(X[:, j])
        for t in (v[:-1] + v[1:]) / 2:
            m = X[:, j] <= t
            s = m.mean() * gini(y[m]) + (1 - m.mean()) * gini(y[~m])
            if s < best[0] - 1e-12:
                best = (s, j, t)
    if best[1] is None:
        return leaf
    _, j, t = best
    m = X[:, j] <= t
    left = grow(X[m], y[m], depth - 1)
    return (j, t, left, grow(X[~m], y[~m], depth - 1))

