def early_stop(losses, patience, min_delta=0.0):
    best, best_epoch, wait = float("inf"), -1, 0
    for epoch, loss in enumerate(losses):
        if loss < best - min_delta:
            best, best_epoch, wait = loss, epoch, 0
        else:
            wait += 1
            if wait >= patience:
                return epoch, best_epoch, best
    return len(losses) - 1, best_epoch, best

import numpy as np

def soft(a, t):
    return np.sign(a) * np.maximum(np.abs(a) - t, 0)

def enet(X, y, alpha, l1r, iters=5000, tol=1e-12):
    n, d = X.shape
    w, r = np.zeros(d), y.astype(float).copy()
    z = (X ** 2).sum(0) / n
    for _ in range(iters):
        big = 0.0
        for j in range(d):
            old = w[j]
            rho = X[:, j] @ r / n + z[j] * old
            w[j] = soft(rho, alpha * l1r) / (z[j] + alpha * (1 - l1r))
            r -= X[:, j] * (w[j] - old)
            big = max(big, abs(w[j] - old))
        if big < tol:
            break
    return w

