def holt(y, a, b, l0, b0, h=5):
    l, t, fit = l0, b0, []
    for v in y:
        fit.append(l + t)
        new = a * v + (1 - a) * (l + t)
        t = b * (new - l) + (1 - b) * t
        l = new
    return np.array(fit), l + t * np.arange(1, h + 1)

