import numpy as np

def linkage(X, method="average"):
    n = len(X)
    D = np.sqrt(((X[:, None] - X[None]) ** 2).sum(-1))
    D = D ** 2 if method == "ward" else D
    np.fill_diagonal(D, np.inf)
    size, ids, Z = np.ones(n), list(range(n)), []
    for s in range(n - 1):
        i, j = np.unravel_index(np.argmin(D), D.shape)
        dij, ni, nj = D[i, j], size[i], size[j]
        if method == "single":
            new = np.minimum(D[i], D[j])
        elif method == "average":
            new = (ni * D[i] + nj * D[j]) / (ni + nj)
        else:
            t = size + ni + nj
            new = ((size + ni) * D[i] + (size + nj) * D[j]
                   - size * dij) / t
        D[i], D[:, i], D[i, i] = new, new, np.inf
        D[j], D[:, j] = np.inf, np.inf
        h = np.sqrt(dij) if method == "ward" else dij
        Z.append([ids[i], ids[j], h, ni + nj])
        ids[i], size[i], size[j] = n + s, ni + nj, 0
    return np.array(Z)

def cut(Z, n, k):
    mem = {i: [i] for i in range(n)}
    for s, (a, b, _, _) in enumerate(Z[: n - k]):
        mem[n + s] = mem.pop(int(a)) + mem.pop(int(b))
    lab = np.zeros(n, int)
    for c, pts in enumerate(mem.values()):
        lab[pts] = c
    return lab

