import numpy as np

def pava(y, w=None):
    w = np.ones(len(y)) if w is None else np.asarray(w, float)
    val, wt, cnt = [], [], []
    for yi, wi in zip(y, w):
        val.append(float(yi)); wt.append(wi); cnt.append(1)
        while len(val) > 1 and val[-2] > val[-1]:
            t = wt[-2] + wt[-1]
            m = (wt[-2] * val[-2] + wt[-1] * val[-1]) / t
            c = cnt[-2] + cnt[-1]
            del val[-1], wt[-1], cnt[-1]
            val[-1], wt[-1], cnt[-1] = m, t, c
    return np.repeat(val, cnt)

