def rbf(A, B, gamma):
    d2 = (A ** 2).sum(1)[:, None] + (B ** 2).sum(1) - 2 * A @ B.T
    return np.exp(-gamma * np.maximum(d2, 0))

def kernel_ridge(X, y, Xt, gamma, lam):
