def log_softmax(z, T=1.0):
    z = z / T
    z = z - z.max(1, keepdims=True)
    return z - np.log(np.exp(z).sum(1, keepdims=True))

def distill_loss(s, t, y, T=2.0, alpha=0.5):
    lps, lpt = log_softmax(s, T), log_softmax(t, T)
    kl = (np.exp(lpt) * (lpt - lps)).sum(1).mean()
    hard = -log_softmax(s)[np.arange(len(y)), y].mean()
    return (1 - alpha) * hard + alpha * T * T * kl

