def tpr_fpr(y, score, t):
    pred = score >= t
    tpr = (pred & (y == 1)).sum() / (y == 1).sum()
    fpr = (pred & (y == 0)).sum() / (y == 0).sum()
    return tpr, fpr

def precision_recall(y, score, t):
    pred = score >= t
    tp = (pred & (y == 1)).sum()
    return tp / max(pred.sum(), 1), tp / (y == 1).sum()

